"""Saved KL gallery tests: artifacts are not silently generated by browser routes."""
import json
from pathlib import Path

from src.web.kl_results import discover_saved_kl_runs


def _write_manifest(root: Path, dataset="2a", subject="A01", run="run123"):
    directory = root / "experiments" / "kl_stage2" / dataset / subject / run
    directory.mkdir(parents=True, exist_ok=True)
    (directory / "01_kl_event_magnitude.png").write_bytes(b"valid-placeholder")
    (directory / "kl_events.csv").write_text("alarm_index,forward\n12,0.15\n")
    manifest = {
        "dataset": dataset, "subject": subject, "run_id": "xx",
        "status": "figures_generated", "event_count": 1,
        "eligible_count": 1, "selected_alarm": 12, "selected_component": "PC1",
        "selected_hotelling_status": "rejected",
        "kl_bins": 8, "kl_pseudocount": 0.5,
        "detector_config": {"pca_components": 2, "window_size": 10},
        "artifacts": ["01_kl_event_magnitude.png", "kl_events.csv",
                      "../secrets.txt", "missing.png"],
    }
    (directory / "manifest.json").write_text(json.dumps(manifest))
    return directory


def test_gallery_scans_only_existing_provenance_backed_artifacts(tmp_path):
    _write_manifest(tmp_path)
    runs = discover_saved_kl_runs(tmp_path, dataset="2a", subject="A01")
    assert len(runs) == 1
    assert runs[0]["eligible_count"] == 1
    assert [a["name"] for a in runs[0]["artifacts"]] == [
        "01_kl_event_magnitude.png", "kl_events.csv",
    ]
    assert not discover_saved_kl_runs(tmp_path, dataset="2b")
    assert not discover_saved_kl_runs(tmp_path / "nonexistent")


def test_kl_gallery_flask_page_reflects_saved_evidence(tmp_path):
    from src.web import app
    old = app.config.get("RESULTS_ROOT")
    app.config["RESULTS_ROOT"] = str(tmp_path)
    try:
        response = app.test_client().get("/results/kl-stage2?dataset=2a&subject=1")
        assert response.status_code == 200
        assert "No exported real-BCI KL figures" in response.get_data(as_text=True)
        _write_manifest(tmp_path)
        response = app.test_client().get("/results/kl-stage2?dataset=2a&subject=1")
        html = response.get_data(as_text=True)
        assert response.status_code == 200
        assert "Slide 12" in html or "KL Stage-II diagnostic" in html
        assert "01_kl_event_magnitude.png" in html
        assert "rejected" in html
        assert "../secrets.txt" not in html
        other = app.test_client().get("/results/kl-stage2?dataset=2b&subject=1")
        assert "No exported real-BCI KL figures" in other.get_data(as_text=True)
    finally:
        if old is None:
            app.config.pop("RESULTS_ROOT", None)
        else:
            app.config["RESULTS_ROOT"] = old
